/**
 * BMI rules (decision 3.1: fixed in the front end). Pure functions only, so
 * they are unit-tested and could later be swapped for an API call without
 * touching the component.
 *
 * Adult BMI = kg / m². Categories (WHO adult ranges) are the same for women
 * and men; the sex field does not change the number (decision C6, K21).
 */

export type UnitSystem = "imperial" | "metric";
export type Sex = "male" | "female";

export type BmiCategory = "underweight" | "healthy" | "overweight" | "obese";

/** Lower bounds of each category, in order. */
export const BMI_THRESHOLDS: readonly { category: BmiCategory; min: number }[] =
  [
    { category: "underweight", min: 0 },
    { category: "healthy", min: 18.5 },
    { category: "overweight", min: 25 },
    { category: "obese", min: 30 },
  ];

const CM_PER_INCH = 2.54;
const KG_PER_LB = 0.45359237;

/**
 * Accepted measurements (plausible adults), defined once in metric so both
 * unit systems accept exactly the same people: a valid value stays valid
 * after a unit switch (R07).
 */
export const MEASUREMENT_LIMITS = {
  heightCm: [90, 250],
  weightKg: [20, 320],
} as const;

/** Round to a step like 0.1 without float noise (2.4, not 2.4000000000000004). */
const roundTo = (n: number, step: number) => {
  const perUnit = Math.round(1 / step);
  return Math.round(n * perUnit) / perUnit;
};

/**
 * Field bounds shown to the user (messages, stepper limits): the metric
 * limits converted and rounded inwards, so every value inside a field's
 * bounds is accepted.
 */
export const LIMITS = {
  metric: {
    heightCm: MEASUREMENT_LIMITS.heightCm,
    weightKg: MEASUREMENT_LIMITS.weightKg,
  },
  imperial: {
    heightFt: [2, 8],
    heightIn: [0, 11],
    /** Total height as [ft, in] pairs, e.g. 2 ft 11.5 in – 8 ft 2.4 in. */
    height: [
      splitFeet(Math.ceil((90 / CM_PER_INCH) * 10) / 10),
      splitFeet(Math.floor((250 / CM_PER_INCH) * 10) / 10),
    ],
    weightLb: [
      Math.ceil((20 / KG_PER_LB) * 10) / 10,
      Math.floor((320 / KG_PER_LB) * 10) / 10,
    ],
  },
} as const;

function splitFeet(totalInches: number): readonly [number, number] {
  const ft = Math.floor(totalInches / 12);
  return [ft, roundTo(totalInches - ft * 12, 0.1)];
}

/** Exact measurement carried across a unit switch (metric). */
export type ExactMeasurement = { cm: number | null; kg: number | null };

export type BmiInput = {
  unit: UnitSystem;
  /** Raw field values (strings, as typed or as displayed after a switch). */
  heightFt: string;
  heightIn: string;
  heightCm: string;
  weight: string;
  /**
   * The exact measurement behind the displayed fields after a unit switch
   * (the fields show rounded values). It is what gets validated and
   * calculated, so switching units never changes the measurement, the BMI
   * or its category (R03). Editing a field drops its part (see
   * `withoutExact`).
   */
  exact?: ExactMeasurement;
};

export type FieldName = "heightFt" | "heightIn" | "heightCm" | "weight";
export type FieldError = "required" | "range";

const parse = (value: string): number | null => {
  if (value.trim() === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

/** Small tolerance for values that only differ by float noise. */
const EPSILON = 1e-9;
const inRange = (n: number, [min, max]: readonly [number, number]) =>
  n >= min - EPSILON && n <= max + EPSILON;

/** Height and weight from the typed fields (null where missing). */
function typedMeasurement(input: BmiInput): ExactMeasurement {
  const weight = parse(input.weight);
  if (input.unit === "metric") {
    return { cm: parse(input.heightCm), kg: weight };
  }
  const ft = parse(input.heightFt);
  const inch = parse(input.heightIn) ?? 0;
  return {
    cm: ft === null ? null : (ft * 12 + inch) * CM_PER_INCH,
    kg: weight === null ? null : weight * KG_PER_LB,
  };
}

/** The measurement to use: exact parts where carried, typed otherwise. */
export function measurement(input: BmiInput): ExactMeasurement {
  const typed = typedMeasurement(input);
  return {
    cm: input.exact?.cm ?? typed.cm,
    kg: input.exact?.kg ?? typed.kg,
  };
}

/** A field edit replaces that part of the exact measurement. */
export function withoutExact(input: BmiInput, field: FieldName): BmiInput {
  if (!input.exact) return input;
  const exact =
    field === "weight"
      ? { ...input.exact, kg: null }
      : { ...input.exact, cm: null };
  return { ...input, exact };
}

/**
 * Validation. Required fields must hold numbers; inches stay within a foot;
 * height and weight are checked as one metric measurement, so both unit
 * systems accept the same range (R07).
 */
export function validate(
  input: BmiInput,
): Partial<Record<FieldName, FieldError>> {
  const errors: Partial<Record<FieldName, FieldError>> = {};
  const heightField: FieldName =
    input.unit === "metric" ? "heightCm" : "heightFt";

  if (parse(input[heightField]) === null) errors[heightField] = "required";
  if (parse(input.weight) === null) errors.weight = "required";
  if (input.unit === "imperial" && input.heightIn.trim() !== "") {
    const inch = parse(input.heightIn);
    if (inch === null) errors.heightIn = "required";
    else if (inch < 0 || inch >= 12) errors.heightIn = "range";
  }

  const { cm, kg } = measurement(input);
  if (!errors[heightField] && !errors.heightIn && cm !== null) {
    if (!inRange(cm, MEASUREMENT_LIMITS.heightCm))
      errors[heightField] = "range";
  }
  if (!errors.weight && kg !== null) {
    if (!inRange(kg, MEASUREMENT_LIMITS.weightKg)) errors.weight = "range";
  }
  return errors;
}

/** Height in cm and weight in kg, or null when the input is not valid. */
export function toMetric(input: BmiInput): { cm: number; kg: number } | null {
  if (Object.keys(validate(input)).length > 0) return null;
  const { cm, kg } = measurement(input);
  return cm === null || kg === null ? null : { cm, kg };
}

export function bmiFromMetric(cm: number, kg: number): number {
  const m = cm / 100;
  return kg / (m * m);
}

/** BMI rounded to one decimal, or null for invalid input. */
export function calculateBmi(input: BmiInput): number | null {
  const metric = toMetric(input);
  if (!metric) return null;
  return Math.round(bmiFromMetric(metric.cm, metric.kg) * 10) / 10;
}

export function categorize(bmi: number): BmiCategory {
  let result: BmiCategory = "underweight";
  for (const { category, min } of BMI_THRESHOLDS)
    if (bmi >= min) result = category;
  return result;
}

/** One decimal, without a trailing ".0". */
const display = (n: number) =>
  String(roundTo(n, 0.1).toFixed(1)).replace(/\.0$/, "");

/**
 * Convert the values when the unit system changes (decision: keep the
 * user's numbers instead of clearing them). The fields show rounded values
 * (cm / kg / lbs to 0.1, whole inches), while the exact measurement is
 * carried in `exact`, so any number of switches back and forth keeps the
 * same measurement, BMI and category (R03). Empty fields stay empty.
 */
export function convertInput(input: BmiInput, to: UnitSystem): BmiInput {
  if (input.unit === to) return input;
  const exact = measurement(input);

  if (to === "metric") {
    return {
      unit: "metric",
      heightFt: "",
      heightIn: "",
      heightCm: exact.cm === null ? "" : display(exact.cm),
      weight: exact.kg === null ? "" : display(exact.kg),
      exact,
    };
  }

  let ft = "";
  let inch = "";
  if (exact.cm !== null) {
    const totalIn = Math.round(exact.cm / CM_PER_INCH);
    ft = String(Math.floor(totalIn / 12));
    inch = String(totalIn % 12);
  }
  return {
    unit: "imperial",
    heightFt: ft,
    heightIn: inch,
    heightCm: "",
    weight: exact.kg === null ? "" : display(exact.kg / KG_PER_LB),
    exact,
  };
}

/**
 * Position (0–1) of a BMI on the scale bar. The four labels sit in equal
 * quarters, so each category maps onto its quarter.
 */
export function scalePosition(bmi: number): number {
  const segments: [number, number][] = [
    [12, 18.5],
    [18.5, 25],
    [25, 30],
    [30, 40],
  ];
  for (let i = 0; i < segments.length; i++) {
    const [lo, hi] = segments[i] ?? [0, 1];
    if (bmi < hi || i === segments.length - 1) {
      const t = Math.min(1, Math.max(0, (bmi - lo) / (hi - lo)));
      return (i + t) / segments.length;
    }
  }
  return 1;
}

/** Fraction (0–1) of the gauge ring to fill: BMI 12 -> 0, BMI 40 -> 1. */
export function gaugeFraction(bmi: number): number {
  return Math.min(1, Math.max(0, (bmi - 12) / (40 - 12)));
}
"use client";

import Image from "next/image";
import { type FormEvent, useId, useState } from "react";
import { ArrowRightCircleIcon } from "@/components/icons";
import { Button } from "@/components/ui/button";
import { Eyebrow } from "@/components/ui/eyebrow";
import { NumberField } from "@/components/ui/number-field";
import { RadioPill } from "@/components/ui/radio-pill";
import { SegmentedControl } from "@/components/ui/segmented-control";
import type { Cta } from "@/content/schemas";
import { TextAction } from "@/features/shared/TextAction";
import { uiCopy } from "@/lib/ui-copy";
import { BmiGauge } from "./BmiGauge";
import { BmiScale } from "./BmiScale";
import {
  type BmiInput,
  calculateBmi,
  categorize,
  convertInput,
  type FieldName,
  LIMITS,
  type Sex,
  type UnitSystem,
  validate,
  withoutExact,
} from "./bmi";

export type BmiCalculatorProps = {
  eyebrow: string;
  tag: string;
  heading: string;
  helper: string;
  optionsCta: Cta | null;
  /** Prefill (stories, or a future profile); empty by default (C9). */
  defaultInput?: BmiInput;
  defaultSex?: Sex;
  /** Show the result for the prefilled values on first render. */
  defaultCalculated?: boolean;
};

const EMPTY: BmiInput = {
  unit: "imperial",
  heightFt: "",
  heightIn: "",
  heightCm: "",
  weight: "",
};

const copy = uiCopy.bmi;

/**
 * BMI / eligibility checker. Rules are pure functions in ./bmi (decision
 * 3.1); nothing is stored (3.2: refresh clears it). The button stays
 * disabled until the input is valid; out-of-range values show a message.
 * Switching units converts the typed values and recalculates an existing
 * result. The result names the chosen sex (C6) — the number itself does
 * not depend on it.
 *
 * Mobile follows the mobile board (one card, gauge on top, no legend/link);
 * from lg it is the form card + result card of the desktop board.
 */
export function BmiCalculator({
  eyebrow,
  tag,
  heading,
  helper,
  optionsCta,
  defaultInput = EMPTY,
  defaultSex = "female",
  defaultCalculated = false,
}: BmiCalculatorProps) {
  const headingId = useId();
  const [input, setInput] = useState<BmiInput>(defaultInput);
  const [sex, setSex] = useState<Sex>(defaultSex);
  const [bmi, setBmi] = useState<number | null>(() =>
    defaultCalculated ? calculateBmi(defaultInput) : null,
  );

  const errors = validate(input);
  const valid = Object.keys(errors).length === 0;
  const imperial = input.unit === "imperial";

  // Typing in a field replaces that part of any exact measurement carried
  // over from a unit switch.
  const set = (field: FieldName) => (value: string) =>
    setInput((current) => ({
      ...withoutExact(current, field),
      [field]: value,
    }));

  const changeUnit = (unit: UnitSystem) => {
    const next = convertInput(input, unit);
    setInput(next);
    if (bmi !== null) setBmi(calculateBmi(next));
  };

  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (valid) setBmi(calculateBmi(input));
  };

  // Only out-of-range values get a message; empty fields just keep the
  // button disabled.
  // Height in ft/in is checked as a whole, so its message names the range.
  const rangeError = (
    field: FieldName,
    min: number,
    max: number,
    unit: string,
  ) => {
    if (errors[field] !== "range") return undefined;
    if (field === "heightFt") {
      const [low, high] = LIMITS.imperial.height;
      return copy.heightRange(low, high);
    }
    return copy.range(min, max, unit);
  };

  const resultText =
    bmi === null
      ? copy.empty
      : copy.result(sex, bmi.toFixed(1), copy.categories[categorize(bmi)]);

  const field = (
    name: FieldName,
    label: string,
    unit: string,
    [min, max]: readonly [number, number],
  ) => (
    <NumberField
      label={label}
      unit={unit}
      value={input[name]}
      onChange={set(name)}
      min={min}
      max={max}
      placeholder="0"
      error={rangeError(name, min, max, unit)}
      incrementLabel={copy.increase(label)}
      decrementLabel={copy.decrease(label)}
    />
  );

  return (
    <div className="mx-auto mt-8 max-w-content rounded-shell lg:bg-surface lg:p-3">
      <div className="relative isolate overflow-hidden rounded-card p-3 shadow-card lg:p-10">
        <Image
          src="/images/bmi-background.webp"
          alt=""
/**
 * Format an amount stored in the currency's minor units with Intl, so the
 * symbol, separators and number of decimals come from the locale and the
 * currency instead of being hard-coded: USD has 2 decimals (cents), JPY 0
 * (yen), KWD 3 (fils). Whole amounts drop the decimals ($200), others keep
 * them ($19.99). An unknown currency code throws instead of showing a
 * wrong amount.
 */
export function formatMoney(
  amountMinor: number,
  currency: string,
  locale = "en-US",
): string {
  if (!Number.isInteger(amountMinor)) {
    throw new RangeError(`amountMinor must be an integer, got ${amountMinor}`);
  }
  const digits = minorDigits(currency);
  const perUnit = 10 ** digits;
  const whole = amountMinor % perUnit === 0;
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: whole ? 0 : digits,
    maximumFractionDigits: whole ? 0 : digits,
  }).format(amountMinor / perUnit);
}

/** Decimal places of a currency's minor unit (ISO 4217, via Intl). */
function minorDigits(currency: string): number {
  return (
    new Intl.NumberFormat("en", {
      style: "currency",
      currency,
    }).resolvedOptions().maximumFractionDigits ?? 2
  );
}
import { z } from "zod";

/**
 * Shared building blocks of the API contract.
 *
 * Conventions (doc/architecture.md §2.5):
 * - Objects use z.object, which ignores unknown keys, so the backend can add
 *   fields without breaking the front end.
 * - Content only: no colours, layout or CSS. Presentation is derived on the
 *   front end (e.g. `category` -> theme).
 * - Stable string ids; references between resources use those ids.
 * - Open string sets (categories, icon keys) stay `string` so an unknown
 *   value falls back to a default instead of failing validation.
 */

/** Stable identifier (slug-like). */
export const Id = z.string().min(1);

/**
 * Where a control leads. `none` = no destination yet: the control only gives
 * press feedback (decisions Q1/Q2/C3).
 */
export const Link = z.discriminatedUnion("type", [
  /** Same-page section, e.g. "weight-loss" -> #weight-loss. */
  z.object({ type: z.literal("anchor"), target: Id }),
  /** In-app route for future pages, e.g. "/login". */
  z.object({ type: z.literal("route"), path: z.string().startsWith("/") }),
  z.object({ type: z.literal("external"), url: z.url() }),
  z.object({ type: z.literal("none") }),
]);

export const Cta = z.object({
  label: z.string().min(1),
  link: Link,
});

/** Text with optional emphasised (highlighted) runs and inline links. */
export const RichTextSegment = z.object({
  text: z.string(),
  emphasis: z.boolean().optional(),
  link: Link.optional(),
});
export const RichText = z.array(RichTextSegment).min(1);

/** Image reference. Dimensions are the intrinsic size of the file. */
export const Image = z.object({
  src: z.string().min(1),
  alt: z.string(),
  width: z.number().int().positive(),
  height: z.number().int().positive(),
});

/**
 * Money in the currency's minor units (cents for USD, yen for JPY, fils
 * for KWD) + ISO 4217 code; formatted with Intl, which knows the decimals.
 */
export const Money = z.object({
  amountMinor: z.number().int().nonnegative(),
  currency: z.string().length(3),
});

export const BillingInterval = z.enum(["week", "month", "year"]);

/** "From $20/mo". */
export const RecurringPrice = Money.extend({ interval: BillingInterval });

