    items.map((language) => (
      <Pill
        key={language.code}
        lang={language.code}
        dir={language.dir}
        selected={selected.has(language.code)}
        onClick={() => onToggle(language.code)}
        tabIndex={clone ? -1 : undefined}
      >
        {language.nativeName}
      </Pill>
    ));

