/**
 * Format an amount stored in the currency's minor units with Intl, so the
 * symbol, separators and number of decimals come from the locale and the
 * currency instead of being hard-coded: USD has 2 decimals (cents), JPY 0
 * (yen), KWD 3 (fils). Whole amounts drop the decimals ($200), others keep
 * them ($19.99). An unknown currency code throws instead of showing a
 * wrong amount.
 */
export function formatMoney(
  amountMinor: number,
  currency: string,
  locale = "en-US",
): string {
  if (!Number.isInteger(amountMinor)) {
    throw new RangeError(`amountMinor must be an integer, got ${amountMinor}`);
  }
  const digits = minorDigits(currency);
  const perUnit = 10 ** digits;
  const whole = amountMinor % perUnit === 0;
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: whole ? 0 : digits,
    maximumFractionDigits: whole ? 0 : digits,
  }).format(amountMinor / perUnit);
}

/** Decimal places of a currency's minor unit (ISO 4217, via Intl). */
function minorDigits(currency: string): number {
  return (
    new Intl.NumberFormat("en", {
      style: "currency",
      currency,
    }).resolvedOptions().maximumFractionDigits ?? 2
  );
}
import { describe, expect, it } from "vitest";
import { formatMoney } from "./money";

describe("formatMoney", () => {
  it("drops decimals for whole amounts", () => {
    expect(formatMoney(20000, "USD")).toBe("$200");
    expect(formatMoney(2000, "USD")).toBe("$20");
  });

  it("keeps two decimals otherwise", () => {
    expect(formatMoney(1999, "USD")).toBe("$19.99");
  });

  it("takes the symbol from the currency and locale", () => {
    expect(formatMoney(20000, "EUR", "en-US")).toBe("€200");
    expect(formatMoney(123456, "USD")).toBe("$1,234.56");
  });

  it("uses each currency's own minor unit (R09)", () => {
    // JPY has no decimals: 2000 minor units are ¥2,000, not ¥20.
    expect(formatMoney(2000, "JPY")).toBe("¥2,000");
    // KWD has three: 1999 fils are 1.999 dinars.
    expect(formatMoney(1999, "KWD")).toMatch(/^KWD\s1\.999$/);
    expect(formatMoney(5000, "KWD")).toMatch(/^KWD\s5$/);
  });

  it("rejects an unknown currency code instead of guessing", () => {
    expect(() => formatMoney(100, "XYZ1")).toThrow(RangeError);
  });

  it("rejects non-integer minor units", () => {
    expect(() => formatMoney(19.5, "USD")).toThrow(RangeError);
  });
});

